using ApiFromLecture.Exceptions; using ApiFromLecture.Validation; using FluentValidation; using System.Globalization;
var builder=WebApplication.CreateBuilder(args); builder.Services.AddControllers(); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen(); builder.Services.AddValidatorsFromAssemblyContaining<CreateProductValidator>(); builder.Services.AddFluentValidationAutoValidation(); builder.Services.Configure<RequestLocalizationOptions>(o=>{o.SetDefaultCulture("en-US");o.SupportedCultures=new[]{new CultureInfo("en-US")};}); builder.Services.AddExceptionHandler<GlobalExceptionHandler>(); builder.Services.AddProblemDetails(); builder.Services.AddSingleton<ProblemDetailsFactory,CustomProblemDetailsFactory>(); var app=builder.Build(); app.UseExceptionHandler(); app.UseRequestLocalization(); if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();} app.MapControllers(); app.Run();
